const checks: [string, boolean][] = [
    ['scoped dark-capable root class present', /g-root_theme_light/.test(html)],
    ['svg chart rendered', /viz-svg/.test(html)],
    ['legend with both series', /Выручка/.test(html) && /Расходы/.test(html)],
    ['line paths drawn', (html.match(/class="viz-line"/g) || []).length === 2],
